KH_PILL = "'.nlps-hero__cta,#nlps button,#nlps a,#nlps-pick button"
KH_HERO = re.compile(r'<a class="nlds-btn[^>]*data-nlps-ev="hero-(wa|sale|world)"')
KH_WA = {"he": "<b>ייעוץ חינם</b>", "en": "<b>Free consultation</b>", "fr": "<b>Conseil gratuit</b>", "ru": "<b>Бесплатная консультация</b>", "ar": "<b>استشارة مجانية</b>"}


def verify_kh(tag):
    """P7.1 (b): the five pages. The order: the H1, the lead, the buttons, the world, the facts, the map (the deals on the Hebrew
    page), then the notice and the article wrapper, then the page's own sections; one H1, one FAQPage, one BreadcrumbList, one
    map; each of the six hreflang links exactly once; the WhatsApp bar's words in the page's language"""
    ok = True
    for lang, path in KH_PAGES.items():
        try:
            s, html = page(path + "?nlv=" + tag)
        except Exception as e:
            print(f"[kh] BAD {path} {e}")
            ok = False
            continue
        body = body_of(html)
        order = KH_ORDER[path]
        pos = [body.find(x) for x in order]
        counts = {"h1": body.count("<h1"), "FAQPage": html.count('"FAQPage"'), "BreadcrumbList": html.count('"BreadcrumbList"'), "map": body.count('id="nlpjx-map"')}
        href = [html.count(h) for h in KH_HREFLANG]
        wa = KH_WA[lang] in body
        # P9a, the phone's first screen (v104.1): the three page-top buttons (the additive law: none removed), before the world; the
        # landing lane in the head; the pill's script counting them as controls; the Russian fonts only on the Russian page
        first = {"hero3": sorted(m.group(1) for m in KH_HERO.finditer(body)) == ["sale", "wa", "world"], "cta_before_world": -1 < body.find("nlps-hero__cta") < body.find('id="nlps"'),
                 "lane": KH_LANE in html, "pill_slot": KH_PILL in body, "cyr": ('id="nadlan-ps-world-cyr"' in html) == (lang == "ru")}
        good = s == 200 and all(p > -1 for p in pos) and pos == sorted(pos) and all(v == 1 for v in counts.values()) and all(v == 1 for v in href) and wa and all(first.values())
        print(f"[kh] {'OK ' if good else 'BAD'} {path} order={list(zip([o[:18] for o in order], pos))} counts={counts} hreflang={href} wa_bar={wa} first_screen={first}")
        ok = ok and good
    return ok


