    ok = s == 200 and all(p > -1 for p in pos) and pos == sorted(pos) and all(body.count(x) == 1 for x in HOME_ORDER if x != '<h1>')
    print(f"[home-order] {'OK ' if ok else 'BAD'} {list(zip([o[:18] for o in HOME_ORDER], pos))}")
